// Helper to sanitize VAT & TAX terms to keep concise wording
export const cleanVatTaxTerms = (terms?: string) => {
  if (!terms) return 'INCLUSIVE of 15% VAT and TAX / AIT.';
  return terms
    .replace(/^All quoted prices are\s*/i, '')
    .replace(/\s*\(Mushak 6\.3\)/gi, '')
    .replace(/\s*applicable\s*/gi, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
};

// Helper to dynamically adjust VAT (10% or 15%) and TAX (5% or 10%) in terms string
export const updateVatTaxString = (
  currentText: string = '',
  newVat?: string,
  newTax?: string,
  forceMode?: 'INCLUSIVE' | 'EXCLUSIVE'
) => {
  const isExclusive = forceMode
    ? forceMode === 'EXCLUSIVE'
    : currentText.toLowerCase().includes('exclusive');
  const prefix = isExclusive ? 'EXCLUSIVE of' : 'INCLUSIVE of';
  let vat = newVat;
  if (!vat) {
    if (currentText.includes('10% VAT')) vat = '10%';
    else if (currentText.includes('15% VAT')) vat = '15%';
    else vat = '15%';
  }
  let tax = newTax;
  if (tax === undefined) {
    if (currentText.includes('10% TAX')) tax = '10%';
    else if (currentText.includes('5% TAX')) tax = '5%';
    else tax = '';
  }
  if (tax) {
    return `${prefix} ${vat} VAT and ${tax} TAX / AIT.`;
  } else {
    return `${prefix} ${vat} VAT and TAX / AIT.`;
  }
};

